(* [comment removed for export] *)
Lemma ASGCALL (x k : Z) M3 model3 LK3 (fx3 : FPState) R3 (ra fbx : Z) (lend : nat) (e0 e1 fbs : Z) (lens : nat) (s0 s1 : Z) :
  GM BX0 M3 model3 LK3 Aw cr -> (x = oq \/ x = orr) -> 32 <= k -> k + 32 <= 504 -> k mod 8 = 0 ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 x -> getr R3 (reg 11) = Z_to_bv 64 (F + k) ->
  PQATSS.binl_at RSEGS M3 x fbx lend e0 e1 -> (lend <= 1)%nat -> PQATSS.binl_at RSEGS M3 (F + k) fbs lens s0 s1 -> (lens <= 1)%nat -> shz M3 (k / 8) ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 x ->
      PQATSS.binl_at RSEGS M4 x (PQATSC.asg_fb fbx fbs lens) lens (PQATSC.asg_w0 e0 s0 lens) (PQATSC.asg_w1 e1 lend lens) ->
      kept (inx x) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 ASGPC M3 model3) K.
