(* [comment removed for export] *)
Lemma CPSCALL M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 32) -> getr R3 (reg 11) = Z_to_bv 64 dn -> shz M3 4 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4 (fd : Z),
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 (F + 32) fd 1%nat NETSA.TEN9 d1 -> Z.land fd 2 = Z.land fbd 2 -> kept (inx (F + 32)) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 CPYPC M3 model3) K.
Proof.
