Lemma CMPCALL2 M3 model3 LK3 (fx3 : FPState) R3 (ra fn fd : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 96) -> getr R3 (reg 11) = Z_to_bv 64 (F + 32) -> shz M3 12 -> shz M3 4 ->
