  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 1 -> kept (fun _ => False) M3 M4 ->
