(* [comment removed for export] *)
Lemma RZCALL M3 model3 LK3 (fx3 : FPState) R3 (ra fbx : Z) (len : nat) (e0 e1 : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 oq -> getr R3 (reg 11) = Z_to_bv 64 2 ->
  PQATSS.binl_at RSEGS M3 oq fbx len e0 e1 -> (len <= 1)%nat ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 oq fbx 2%nat (if Nat.eqb len 0 then 0 else e0) 0 -> kept (inx oq) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
