(* [comment removed for export] *)
Lemma RDCALL M3 model3 LK3 (fx3 : FPState) R3 (ra fbx : Z) (e0 e1 : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 oq ->
  PQATSS.binl_at RSEGS M3 oq fbx 2%nat e0 e1 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 -> getr R4 (reg 10) = Z_to_bv 64 oq ->
      PQATSS.binl_at RSEGS M4 oq (PQATSS.wfb fbx e0 e1) (PQATSS.wlen e0 e1) e0 e1 -> kept (inx oq) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
