  ((F + 32 <= y /\ y + 32 <= F + 504) \/ y = o \/ y = oq \/ y = orr) -> (forall a, y <= a < y + 32 -> ~ Wx a) -> 0 <= y -> y + 32 <= 2 ^ 64 ->
