(* [comment removed for export] *)
Lemma MSCALL M3 model3 LK3 (fx3 : FPState) R3 (ra : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 (F + 168) -> getr R3 (reg 11) = Z_to_bv 64 0 -> getr R3 (reg 12) = Z_to_bv 64 24 ->
  shz M3 20 ->
  (forall R4 (M4 : mem) model4,
      GM BX0 M4 model4 LK3 Aw cr -> regs_preserved R3 R4 -> PM.zeros_at M4 (F + 168) 24 -> kept (fun a => F + 168 <= a < F + 192) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 MSPC M3 model3) K.
Proof.
